                'Indonesian' => 'Anda tampaknya mendapatkan rasa kepuasan di seluruh pekerjaan dan kehidupan Anda secara umum, dan menghabiskan hari-hari yang memuaskan. Ini adalah keadaan yang sangat indah.',
            ],
        ];

        /*
         * Mapping from CSV Category (Japanese) to Database Scale Name (English).
         * Note: 'Scale' column in CSV acts as 'level' in database.
         */
        $categoryToScaleName = [
            '心理的な仕事の負担（量）' => 'Psychological work load (Quantity)',
            '心理的な仕事の負担（質）' => 'Psychological work load (Quality)',
            '自覚的な身体的負担' => 'Subjective physical burden',
            '職場環境' => 'Stress from work environment',
            '仕事のコントロール度' => 'Job control',
            '技能の活用度' => 'Skill utilization',
            '仕事の適性度' => 'Job suitability',
            // 'general_intro' => null (handled explicitly)
            '働きがい' => 'Job satisfaction',
            '活気' => 'Vigor',
            'イライラ感' => 'Irritability',
            '疲労感' => 'Fatigue',
            '不安感' => 'Anxiety',
            '抑うつ感' => 'Depression',
            '上司からのサポート' => 'Support from supervisors',
            '同僚からのサポート' => 'Support from colleagues',
            '家族・友人からのサポート' => 'Support from family/friends',
            '仕事や生活の満足度' => 'Work/Family satisfaction',
        ];

        $allScales = Scale::all()->keyBy('name');

        foreach ($csvData as $row) {
            $category = trim($row['Category']);
            $csvScale = trim($row['Scale']); // Acts as 'level'

            $scaleId = null;
            if ($category === 'general_intro') {
                $scaleId = null;
                $csvScale = 'all';
            } elseif (isset($categoryToScaleName[$category])) {
                $targetName = $categoryToScaleName[$category];
                if (isset($allScales[$targetName])) {
                    $scaleId = $allScales[$targetName]->id;
                }
            }

            // Create Comment
            $comment = Comment::create([
                'scale_id' => $scaleId,
                'level' => $csvScale,
            ]);

            // Create Translations
            $translations = [
                'ja' => $row['Japanese'],
                'en' => $row['English'],
                'zh-CN' => $row['Chinese_Simp'],
                'zh-TW' => $row['Chinese_Trad'],
                'vi' => $row['Vietnamese'],
                'tl' => $row['Tagalog'],
                'pt' => $row['Portuguese'],
                'es' => $row['Spanish'],
                'th' => $row['Thai'],
                'id' => $row['Indonesian'],
            ];

            foreach ($translations as $langCode => $content) {
                if (! empty($content)) {
                    $comment->translations()->create([
                        'lang_code' => $langCode,
                        'content' => $content,
                    ]);
                }
            }
        }
    }
